import{_ as o,o as e,c as r,ag as t}from"./chunks/framework.QfQ7DfGu.js";const c=JSON.parse('{"title":"龙芯实验室开源仓库","description":"","frontmatter":{"title":"龙芯实验室开源仓库","outline":"deep"},"headers":[],"relativePath":"repos/loongsonlab.md","filePath":"repos/loongsonlab.md"}'),h={name:"repos/loongsonlab.md"};function n(i,a,l,p,g,s){return e(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="loongsonlab-开源仓库" tabindex="-1">LoongsonLab 开源仓库 <a class="header-anchor" href="#loongsonlab-开源仓库" aria-label="Permalink to &quot;LoongsonLab 开源仓库&quot;">​</a></h1><h2 id="模拟器" tabindex="-1">模拟器 <a class="header-anchor" href="#模拟器" aria-label="Permalink to &quot;模拟器&quot;">​</a></h2><h3 id="la-emu" tabindex="-1">LA_EMU <a class="header-anchor" href="#la-emu" aria-label="Permalink to &quot;LA_EMU&quot;">​</a></h3><p>LA_EMU 是一个 LoongArch64 模拟器，支持整型，浮点，向量指令集。能够启动Linux, 运行大型测试。</p><p>仓库链接：<a href="https://github.com/Open-ChipHub/LA_EMU.git" target="_blank" rel="noreferrer">https://github.com/Open-ChipHub/LA_EMU.git</a></p><h3 id="lars" tabindex="-1">LARS <a class="header-anchor" href="#lars" aria-label="Permalink to &quot;LARS&quot;">​</a></h3><p>LARS,龙芯汇编程序运行模拟器（LoongArch Assembler and Runtime Simulator），是支持LoongArch 32精简指令集的汇编程序模拟器。实现汇编程序的编写、编译、运行、调试等功能，并且提供了诸多如数据通路模拟、分支记录等拓展功能，以供LoongArch汇编语言的学习。</p><p>仓库链接：<a href="https://github.com/LoongsonLab/LARS.git" target="_blank" rel="noreferrer">https://github.com/LoongsonLab/LARS.git</a></p><h2 id="开源异构处理器平台" tabindex="-1">开源异构处理器平台 <a class="header-anchor" href="#开源异构处理器平台" aria-label="Permalink to &quot;开源异构处理器平台&quot;">​</a></h2><h3 id="异构多核处理器" tabindex="-1">异构多核处理器 <a class="header-anchor" href="#异构多核处理器" aria-label="Permalink to &quot;异构多核处理器&quot;">​</a></h3><p>LoongChipX是一个开源的异构多核处理器平台。包括多发射乱序高性能处理器LabCore364，五级流水的LabCore164，支持LoongArch32的小核LabCore132，包括后续开发中的六发射高性能处理器。我们旨在构建一个支持多核异构的处理器平台，提供仿真，验证的功能。包括相应的软件支持，如linux内核，gcc和llvm编译器等。</p><p>仓库链接：<a href="https://github.com/Open-ChipHub/LoongChipX.git" target="_blank" rel="noreferrer">https://github.com/Open-ChipHub/LoongChipX.git</a></p><h3 id="dv验证工具" tabindex="-1">DV验证工具 <a class="header-anchor" href="#dv验证工具" aria-label="Permalink to &quot;DV验证工具&quot;">​</a></h3><p>LA64是一个LA64架构的随机代码生成器，用于生成随机代码，作为处理器输入，与模拟器运行结果进行对比。</p><p>仓库链接：<a href="https://github.com/Open-ChipHub/loong64-dv.git" target="_blank" rel="noreferrer">https://github.com/Open-ChipHub/loong64-dv.git</a></p><h3 id="调试工具" tabindex="-1">调试工具 <a class="header-anchor" href="#调试工具" aria-label="Permalink to &quot;调试工具&quot;">​</a></h3><p>OpenOCD 是一款上板调试工具，已实现并支持 LoongChipX 平台。</p><p>仓库链接：<a href="https://github.com/Open-ChipHub/OpenOCD.git" target="_blank" rel="noreferrer">https://github.com/Open-ChipHub/OpenOCD.git</a></p><h3 id="软件开发工具包" tabindex="-1">软件开发工具包 <a class="header-anchor" href="#软件开发工具包" aria-label="Permalink to &quot;软件开发工具包&quot;">​</a></h3><p>LoongArch-SDK 提供了 LoongArch 架构下构建系统或软件所需要的开发工具包，包括：交叉编译工具,rootfs, uefi 固件等。</p><p>仓库链接：<a href="https://github.com/Open-ChipHub/LoongArch-SDK.git" target="_blank" rel="noreferrer">https://github.com/Open-ChipHub/LoongArch-SDK.git</a></p><h2 id="开源操作系统" tabindex="-1">开源操作系统 <a class="header-anchor" href="#开源操作系统" aria-label="Permalink to &quot;开源操作系统&quot;">​</a></h2><h3 id="starry-os" tabindex="-1">Starry OS <a class="header-anchor" href="#starry-os" aria-label="Permalink to &quot;Starry OS&quot;">​</a></h3><p>StarryOS，一个基于ArceOS实现的宏内核。</p><p>仓库链接：<a href="https://github.com/LoongsonLab/StarryOS-LoongArch.git" target="_blank" rel="noreferrer">https://github.com/LoongsonLab/StarryOS-LoongArch.git</a></p><h3 id="rt-thread" tabindex="-1">RT-Thread <a class="header-anchor" href="#rt-thread" aria-label="Permalink to &quot;RT-Thread&quot;">​</a></h3><p>RT-Thread 是一个开源的物联网端实时操作系统(RTOS)。</p><p>仓库链接：<a href="https://github.com/LoongsonLab/rt-thread.git" target="_blank" rel="noreferrer">https://github.com/LoongsonLab/rt-thread.git</a></p><h2 id="开放文档" tabindex="-1">开放文档 <a class="header-anchor" href="#开放文档" aria-label="Permalink to &quot;开放文档&quot;">​</a></h2><p>关于 LoongChipX 平台的开放说明文档，仓库链接：<a href="https://github.com/Open-ChipHub/LoongChipX-doc.git" target="_blank" rel="noreferrer">https://github.com/Open-ChipHub/LoongChipX-doc.git</a></p><p>关于 LoongArch 架构与操作系统底层交互的开放说明我而当，仓库链接：<a href="https://github.com/LoongsonLab/OS_kernel_with_loong64_doc.git" target="_blank" rel="noreferrer">https://github.com/LoongsonLab/OS_kernel_with_loong64_doc.git</a></p>',31)])])}const u=o(h,[["render",n]]);export{c as __pageData,u as default};
